{
  "violated_invariants": ["I2", "I3", "I4"],
  "evidence": {
    "I2": "get_invoice fetches by invoice ID without checking the current tenant.",
    "I3": "Webhook deduplication is non-atomic: processing is marked complete only after effects, allowing duplicate deliveries to insert distinct OrderPaid outbox rows.",
    "I4": "mark_paid changes order status to paid without invalidating its cache entry."
  },
  "citations": [
    "service/invoice_service.py:get_invoice",
    "store/invoice_repo.py:get_by_id",
    "service/payment_service.py:handle_payment_webhook",
    "store/outbox.py:insert",
    "service/order_service.py:mark_paid"
  ]
}

{
  "findings": [
    {
      "id": "n_plus_1",
      "severity": "medium",
      "summary": "list_orders fetches tenant-scoped rows, then redundantly calls get_order for every row, causing up to N additional repository lookups."
    }
  ],
  "max_severity": "medium",
  "auth_ok": true,
  "citations": [
    "service/order_service.py:list_orders",
    "service/order_service.py:get_order",
    "store/order_repo.py:list_by_tenant",
    "api/orders.py:handle_list_orders"
  ]
}

{
  "root_cause": "process_once acknowledges each row before publishing it; a crash afterward leaves acked=true, so claim_batch never retries the unpublished event.",
  "fix_function": "worker.outbox_worker.process_once",
  "citations": [
    "worker/outbox_worker.py:process_once",
    "store/outbox.py:claim_batch",
    "store/outbox.py:ack"
  ]
}

{
  "touch_files": ["service/payment_service.py"],
  "plan_steps": [
    "After the duplicate check succeeds, record webhook_id in processed_webhooks before performing payment or outbox writes.",
    "Only then insert the payment, OrderPaid outbox event, and update the order."
  ],
  "idempotency_change": "Move _mark_processed(webhook_id) from after order_service.mark_paid to immediately after the duplicate check and before outbox.insert(order_paid(...)).",
  "citations": [
    "service/payment_service.py:handle_payment_webhook",
    "service/payment_service.py:_mark_processed"
  ]
}
